package com.bank.bitonic.service;

import java.util.logging.Logger;

// Searches a bitonic array: find peak, then search each monotonic side.
public class BitonicSearchService {
    private static final Logger log = Logger.getLogger(BitonicSearchService.class.getName());

    public int firstIndexOf(int[] prices, int key) {
        int peak = findPeak(prices);
        int left = search(prices, key, 0, peak, true);    // ascending side
        if (left != -1) {
            log.info(() -> "Key " + key + " found on rising side at " + left);
            return left;                                   // smaller index wins
        }
        int right = search(prices, key, peak + 1, prices.length - 1, false); // descending side
        log.info(() -> "Key " + key + " search returned index " + right + " on falling side");
        return right;
    }

    private int findPeak(int[] a) {
        int start = 0, end = a.length - 1;
        while (start < end) {
            int mid = start + (end - start) / 2;
            if (a[mid] > a[mid + 1]) end = mid; else start = mid + 1;
        }
        return start;
    }

    private int search(int[] a, int key, int start, int end, boolean ascending) {
        while (start <= end) {
            int mid = start + (end - start) / 2;
            if (a[mid] == key) return mid;
            if (ascending) {
                if (key < a[mid]) end = mid - 1; else start = mid + 1;
            } else {
                if (key < a[mid]) start = mid + 1; else end = mid - 1; // reversed
            }
        }
        return -1;
    }
}
